-- ============================================================================
-- MEDDIET PRO — INSTALADOR DE BASE DE DATOS MYSQL / MARIADB
-- Cocina Mediterránea Española Hipocalórica (1.350 - 1.600 kcal/día)
-- CERO Marisco | CERO Bacalao | CERO Rape | Viernes Fijo: Arroz a la Cubana
-- ============================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `saved_menus`;
DROP TABLE IF EXISTS `weekly_plans`;
DROP TABLE IF EXISTS `recipe_steps`;
DROP TABLE IF EXISTS `recipe_ingredients`;
DROP TABLE IF EXISTS `ingredients`;
DROP TABLE IF EXISTS `recipes`;

-- ----------------------------------------------------------------------------
-- 1. TABLA: recipes (Catálogo de 42 recetas españolas reales hipocalóricas)
-- ----------------------------------------------------------------------------
CREATE TABLE `recipes` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `slug` VARCHAR(120) NOT NULL,
  `name` VARCHAR(180) NOT NULL,
  `category` ENUM('arroz_fijo','legumbre','pescado','ave_carne_magra','verdura_huevo') NOT NULL,
  `meal_slot` ENUM('lunch','dinner','both') NOT NULL DEFAULT 'both',
  `seasons` SET('primavera','verano','otono','invierno') NOT NULL,
  `kcal` INT UNSIGNED NOT NULL COMMENT 'Kcal por comensal',
  `protein_g` INT UNSIGNED NOT NULL COMMENT 'Proteínas (g) por comensal',
  `carbs_g` INT UNSIGNED NOT NULL COMMENT 'Hidratos (g) por comensal',
  `fat_g` INT UNSIGNED NOT NULL COMMENT 'Grasas (g) por comensal',
  `prep_minutes` INT UNSIGNED NOT NULL COMMENT 'Tiempo activo en minutos (<35 min)',
  `cooking_method` VARCHAR(60) NOT NULL,
  `image_url` VARCHAR(255) NOT NULL,
  `youtube_url` VARCHAR(255) NOT NULL,
  `chef_tip` TEXT NOT NULL,
  `batch_prep_tip` TEXT NOT NULL,
  `is_friday_fixed` TINYINT(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_recipes_slug` (`slug`),
  KEY `idx_recipes_category` (`category`),
  KEY `idx_recipes_slot` (`meal_slot`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------------------------------------------------------
-- 2. TABLA: ingredients (Ingredientes normalizados por pasillo de supermercado)
-- ----------------------------------------------------------------------------
CREATE TABLE `ingredients` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(120) NOT NULL,
  `aisle` ENUM('Frutas y Verduras','Carnicería y Aves','Pescadería','Legumbres y Arroces','Huevos y Lácteos','Despensa') NOT NULL,
  `unit` VARCHAR(25) NOT NULL,
  `rounding_step` DECIMAL(8,2) NOT NULL DEFAULT 5.00,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ingredient_name` (`name`),
  KEY `idx_ingredient_aisle` (`aisle`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------------------------------------------------------
-- 3. TABLA: recipe_ingredients (Cantidades exactas por 1 comensal)
-- ----------------------------------------------------------------------------
CREATE TABLE `recipe_ingredients` (
  `recipe_id` INT UNSIGNED NOT NULL,
  `ingredient_id` INT UNSIGNED NOT NULL,
  `amount_per_diner` DECIMAL(8,2) NOT NULL,
  `notes` VARCHAR(120) DEFAULT NULL,
  PRIMARY KEY (`recipe_id`, `ingredient_id`),
  CONSTRAINT `fk_ri_recipe` FOREIGN KEY (`recipe_id`) REFERENCES `recipes` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_ri_ingredient` FOREIGN KEY (`ingredient_id`) REFERENCES `ingredients` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------------------------------------------------------
-- 4. TABLA: recipe_steps (Pasos numerados con temporizador para Modo Cocina)
-- ----------------------------------------------------------------------------
CREATE TABLE `recipe_steps` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `recipe_id` INT UNSIGNED NOT NULL,
  `step_number` TINYINT UNSIGNED NOT NULL,
  `instruction` TEXT NOT NULL,
  `timer_seconds` INT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `idx_steps_recipe` (`recipe_id`, `step_number`),
  CONSTRAINT `fk_steps_recipe` FOREIGN KEY (`recipe_id`) REFERENCES `recipes` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------------------------------------------------------
-- 5. TABLA: weekly_plans (Plan semanal activo de 14 tomas: Lunes a Domingo)
-- ----------------------------------------------------------------------------
CREATE TABLE `weekly_plans` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `day_of_week` ENUM('lunes','martes','miercoles','jueves','viernes','sabado','domingo') NOT NULL,
  `meal_type` ENUM('comida','cena') NOT NULL,
  `recipe_id` INT UNSIGNED NOT NULL,
  `is_locked` TINYINT(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_day_meal` (`day_of_week`, `meal_type`),
  CONSTRAINT `fk_wp_recipe` FOREIGN KEY (`recipe_id`) REFERENCES `recipes` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------------------------------------------------------
-- 6. TABLA: saved_menus (Histórico de menús semanales guardados por el usuario)
-- ----------------------------------------------------------------------------
CREATE TABLE `saved_menus` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `menu_name` VARCHAR(140) NOT NULL,
  `season` ENUM('primavera','verano','otono','invierno') NOT NULL DEFAULT 'primavera',
  `diners` TINYINT UNSIGNED NOT NULL DEFAULT 2,
  `plan_json` JSON NOT NULL,
  `avg_daily_kcal` INT UNSIGNED NOT NULL DEFAULT 1420,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ============================================================================
-- VOLCADO DE DATOS INICIALES: INGREDIENTES (46 ingredientes base)
-- ============================================================================

-- ============================================================================
-- VOLCADO DE DATOS INICIALES: 42 RECETAS MEDITERRÁNEAS ESPAÑOLAS REALES
-- ============================================================================
-- 1. PLATO FIJO DEL VIERNES A MEDIODÍA
(1, 'arroz-blanco-cubana-ligero', 'Arroz blanco a la cubana (versión ligera)', 'arroz_fijo', 'lunch', 'primavera,verano,otono,invierno', 465, 16, 68, 13, 20, 'Hervido + Plancha sin fritura', 'assets/img/arroz_cubana.jpg', 'https://www.youtube.com/results?search_query=receta+casera+arroz+a+la+cubana+saludable+española', 'Sustituimos la fritura en abundante aceite por huevo a la plancha antiadherente con gota de AOVE, tomate natural reducido a fuego lento con albahaca y medio plátano dorado en seco sobre sartén caliente. Ahorras más de 280 kcal manteniendo todo el sabor tradicional.', 'Deja la salsa de tomate casera lista el domingo en tarro de cristal y el arroz cocido al dente (enfriado rápido para generar almidón resistente prebiótico).', 1),

-- 2 a 10: LEGUMBRES (Exactamente 2 comidas por semana)
(2, 'lentejas-estofadas-verduras', 'Lentejas pardinas estofadas con verduras de la huerta', 'legumbre', 'lunch', 'otono,invierno,primavera', 410, 22, 54, 9, 25, 'Guiso suave tradicional', 'assets/img/legumbres.jpg', 'https://www.youtube.com/results?search_query=receta+casera+lentejas+con+verduras+viudas+española', 'No añadas chorizo ni panceta: tritura una cucharada de las propias verduras cocidas con pimentón de la Vera y un hilo de AOVE en crudo al final para conseguir un caldo trabado, sedoso y lleno de aroma.', 'Se conserva 4 días impecable en nevera; de hecho, gana sabor de un día para otro.', 0),
(3, 'garbanzos-espinacas-pimenton', 'Garbanzos con espinacas frescas y pimentón de la Vera', 'legumbre', 'lunch', 'otono,invierno,primavera', 395, 20, 48, 11, 20, 'Rehogado tradicional andaluz', 'assets/img/garbanzos.jpg', 'https://www.youtube.com/results?search_query=receta+casera+garbanzos+con+espinacas+andaluza', 'En lugar de freír pan para el majado, machaca en el mortero ajo asado, comino en grano y 10 garbanzos cocidos para espesar la salsa sin sumar harinas ni grasa.', 'Puedes dejar el sofrito de ajo, pimentón y tomate preparado del domingo.', 0),
(4, 'potaje-alubias-blancas-acelgas', 'Potaje de alubias blancas con acelgas y zanahoria', 'legumbre', 'lunch', 'otono,invierno', 385, 21, 50, 8, 25, 'Cuchara de cocción lenta', 'assets/img/alubias_ensalada.jpg', 'https://www.youtube.com/results?search_query=receta+casera+potaje+alubias+blancas+con+acelgas', 'Añade las pencas de acelga picadas finas al principio y las hojas verdes solo en los últimos 5 minutos para preservar su color esmeralda y ácido fólico.', 'Congela o refrigera en raciones individuales listo para calentar.', 0),
(5, 'empedrat-catalan-alubias-huevo', 'Empedrat catalán de alubias con tomate, pimiento y huevo duro', 'legumbre', 'lunch', 'primavera,verano', 380, 22, 44, 11, 15, 'Fresco de montaje rápido', 'assets/img/alubias_ensalada.jpg', 'https://www.youtube.com/results?search_query=receta+empedrat+de+alubias+tradicional+saludable', 'Versión 100% libre de pescado salado: combinamos alubia blanca muy tierna con huevo duro campero, pimiento rojo y verde en brunoise fina, tomate concassé y aceitunas picadas.', 'Cuece los huevos y deja la picada de hortalizas en táper hermético.', 0),
(6, 'ensalada-templada-lentejas-pimientos', 'Lentejas en ensalada templada con pimientos asados y cebolleta', 'legumbre', 'lunch', 'primavera,verano', 375, 19, 49, 10, 15, 'Templado / Ensalada completa', 'assets/img/alubias_ensalada.jpg', 'https://www.youtube.com/results?search_query=receta+ensalada+de+lentejas+con+verduras+española', 'Aliña las lentejas aún tibias con vinagre de Jerez viejo y pimientos asados en su propio jugo; la legumbre absorbe el aliño reduciendo a la mitad la necesidad de aceite.', 'Usa los pimientos asados en la bandeja del Batch Cooking dominical.', 0),
(7, 'garbanzos-salteados-calabacin-setas', 'Garbanzos salteados con calabacín, setas y ajo tierno', 'legumbre', 'lunch', 'primavera,verano,otono', 390, 19, 47, 11, 18, 'Salteado en sartén a fuego vivo', 'assets/img/garbanzos.jpg', 'https://www.youtube.com/results?search_query=receta+garbanzos+salteados+con+setas+y+verduras', 'Seca bien los garbanzos cocidos antes de saltearlos para que queden ligeramente dorados por fuera y tiernos por dentro con solo 1 cucharadita de AOVE.', 'Deja las setas y el calabacín limpios y cortados en dados.', 0),
(8, 'alubias-estofadas-calabaza-puerro', 'Alubias blancas estofadas con calabaza asada y puerro', 'legumbre', 'lunch', 'otono,invierno', 395, 20, 52, 9, 25, 'Estofado meloso', 'assets/img/alubias_ensalada.jpg', 'https://www.youtube.com/results?search_query=receta+alubias+blancas+con+calabaza+y+verduras', 'La calabaza cacahuete se deshace parcialmente en el caldo aportando un dulzor natural y una textura cremosa sin añadir nata ni grasas saturadas.', 'Guisa la base de puerro y calabaza durante el Batch Cooking.', 0),
(9, 'pipirrana-garbanzos-atun-fresco', 'Pipirrana jaenera con garbanzos y dados de atún fresco a la plancha', 'legumbre', 'lunch', 'primavera,verano', 420, 31, 42, 12, 15, 'Fresco + Plancha rápida', 'assets/img/alubias_ensalada.jpg', 'https://www.youtube.com/results?search_query=receta+ensalada+garbanzos+pipirrana+española', 'El contraste entre la pipirrana bien fría de tomate, pepino y pimiento verde y los dados de atún fresco marcados vuelta y vuelta eleva la proteína saciante.', 'Pica la pipirrana con antelación y marca el atún justo al servir.', 0),
(10, 'lentejas-alcachofas-zanahoria', 'Guiso ligero de lentejas con corazones de alcachofa y zanahoria', 'legumbre', 'lunch', 'invierno,primavera', 400, 22, 51, 9, 28, 'Guiso tradicional en cazuela', 'assets/img/legumbres.jpg', 'https://www.youtube.com/results?search_query=receta+lentejas+con+alcachofas+casera+española', 'La cinarina de la alcachofa favorece la digestión hepática y aporta un toque ligeramente amargo delicioso que equilibra el dulzor de la zanahoria.', 'Puedes usar corazones de alcachofa naturales blanqueados el domingo.', 0),

-- 11 a 20: PESCADOS PERMITIDOS (Exactamente 2 noches por semana — SIN marisco, SIN bacalao, SIN rape)
(11, 'merluza-plancha-ajillo-trigueros', 'Merluza a la plancha al ajillo ligero con espárragos trigueros', 'pescado', 'dinner', 'primavera,verano,otono,invierno', 310, 34, 8, 14, 15, 'Plancha antiadherente', 'assets/img/pescado.jpg', 'https://www.youtube.com/results?search_query=receta+merluza+a+la+plancha+con+ajo+y+perejil+española', 'Dora las láminas de ajo en apenas 5 ml de AOVE y desglasa la sartén con un chorrito de zumo de limón y caldo de verduras para lograr una emulsión brillante y ligera.', 'Lava y quita el tallo leñoso a los trigueros con antelación.', 0),
(12, 'lubina-horno-patata-panadera', 'Lubina al horno con patata panadera medida y limón', 'pescado', 'dinner', 'primavera,verano,otono,invierno', 355, 33, 24, 13, 25, 'Horno tradicional', 'assets/img/pescado_horno.jpg', 'https://www.youtube.com/results?search_query=receta+lubina+al+horno+con+patatas+panadera+española', 'En vez de freír las patatas panadera en sartén, ásalas primero 15 minutos en el horno con cebolla en juliana y medio vaso de caldo de verduras: quedan tiernas y ahorras 200 kcal.', 'Puedes dejar la cama de patata y cebolla pre-asada en la bandeja.', 0),
(13, 'dorada-espalda-horno-tomate', 'Dorada a la espalda al horno con juliana de cebolla y tomate', 'pescado', 'dinner', 'primavera,verano,otono,invierno', 330, 35, 11, 14, 22, 'Horno a la espalda', 'assets/img/pescado_horno.jpg', 'https://www.youtube.com/results?search_query=receta+dorada+a+la+espalda+al+horno+española', 'Hornear la dorada abierta sobre una cama húmeda de tomate maduro y cebolla evita que el pescado se reseque sin necesidad de bañar la pieza en aceite.', 'Deja la cama de cebolla y tomate pochada en el Batch Cooking.', 0),
(14, 'salmon-papillote-puerro-zanahoria', 'Salmón al papillote con juliana de puerro, zanahoria y eneldo', 'pescado', 'dinner', 'otono,invierno,primavera', 390, 34, 9, 22, 20, 'Papillote al vapor en su jugo', 'assets/img/pescado_azul.jpg', 'https://www.youtube.com/results?search_query=receta+salmon+al+papillote+con+verduras+española', 'El salmón ya es rico en ácidos grasos cardiosaludables Omega-3; cocinado en papillote cerrado con verduras en juliana no necesita ni una sola gota de aceite añadido.', 'Corta las verduras en bastones finos y guárdalas en bolsa hermética.', 0),
(15, 'trucha-navarra-ligera-horno', 'Trucha a la navarra ligera al horno con jamón serrano magro', 'pescado', 'dinner', 'primavera,otono,invierno', 325, 36, 6, 16, 18, 'Horno sin rebozado', 'assets/img/pescado_azul.jpg', 'https://www.youtube.com/results?search_query=receta+trucha+a+la+navarra+al+horno+ligera', 'Eliminamos el enharinado y la fritura clásica horneando la trucha rellena de una loncha fina de jamón serrano magro sin tocino; el propio jamón sala y jugosea el pescado.', 'Acompaña con ensalada verde o verduras al vapor.', 0),
(16, 'emperador-plancha-calabacin-asado', 'Emperador a la plancha con picada de ajo, perejil y calabacín', 'pescado', 'dinner', 'primavera,verano,otono', 320, 35, 8, 15, 14, 'Plancha bien caliente', 'assets/img/pescado_azul.jpg', 'https://www.youtube.com/results?search_query=receta+emperador+a+la+plancha+con+ajo+y+perejil', 'Saca el filete de emperador de la nevera 10 minutos antes y márcalo solo 90 segundos por cara a fuego fuerte para que conserve todos sus jugos interiores.', 'Prepara un bote pequeño de picada de ajo, perejil y limón.', 0),
(17, 'sardinas-asadas-horno-pimientos', 'Sardinas frescas asadas al horno con pimientos verdes y tomate', 'pescado', 'dinner', 'verano,primavera', 340, 31, 10, 18, 20, 'Horno sobre papel vegetal', 'assets/img/pescado_azul.jpg', 'https://www.youtube.com/results?search_query=receta+sardinas+al+horno+sin+olor+española', 'Hornear las sardinas a 200 °C con rodajas de limón y perejil durante 10 minutos evita olores en la cocina y mantiene intacto todo su calcio y Omega-3.', 'Acompaña con pimientos asados del domingo.', 0),
(18, 'boquerones-horno-limon-perejil', 'Boquerones frescos al horno al limón con ensalada de brotes', 'pescado', 'dinner', 'primavera,verano', 295, 30, 7, 15, 16, 'Horno rápido (8 min)', 'assets/img/pescado_azul.jpg', 'https://www.youtube.com/results?search_query=receta+boquerones+al+horno+con+limon+y+perejil', 'Abiertos en mariposa en una bandeja con ajo picado, perejil, zumo de limón y pulverización de AOVE reemplazan a los boquerones fritos con un 65% menos de calorías.', 'Pide en la pescadería los boquerones abiertos sin espina central.', 0),
(19, 'bonito-con-tomate-casero-ligero', 'Bonito del norte con salsa de tomate casera y pimientos', 'pescado', 'both', 'verano,otono,primavera', 360, 37, 14, 15, 22, 'Guiso suave corto', 'assets/img/pescado_azul.jpg', 'https://www.youtube.com/results?search_query=receta+bonito+con+tomate+casero+tradicional+española', 'Apaga el fuego en cuanto incorpores los tacos de bonito a la salsa de tomate hirviendo y tapa la cazuela 3 minutos: se cocina con el calor residual quedando súper jugoso.', 'Usa la misma salsa de tomate casera preparada en el Batch Cooking.', 0),
(20, 'atun-fresco-encebollado-laurel', 'Atún fresco encebollado ligero al laurel con pimientos asados', 'pescado', 'dinner', 'primavera,verano,otono', 350, 36, 12, 16, 20, 'Cazuela tradicional gaditana', 'assets/img/pescado_azul.jpg', 'https://www.youtube.com/results?search_query=receta+atun+encebollado+tradicional+gaditano', 'Pocha la cebolla muy despacio con tapa y unas cucharadas de caldo de verduras para que caramelice en sus propios azúcares sin requerir apenas aceite.', 'La cebolla pochada del domingo reduce este plato a 6 minutos.', 0),

-- 21 a 31: AVES Y CARNES MAGRAS (Comidas y Cenas)
(21, 'pechuga-pollo-plancha-escalivada', 'Pechuga de pollo de corral a la plancha con escalivada catalana', 'ave_carne_magra', 'both', 'primavera,verano,otono,invierno', 345, 38, 14, 13, 15, 'Plancha + Verdura asada', 'assets/img/aves.jpg', 'https://www.youtube.com/results?search_query=receta+escalivada+tradicional+con+pollo+a+la+plancha', 'Marina los filetes de pollo con zumo de limón, ajo machacado y tomillo 15 minutos antes de pasarlos por la plancha: rompe las fibras y queda tiernísimo.', 'La escalivada (pimiento rojo, berenjena y cebolla) se asa entera el domingo.', 0),
(22, 'pollo-ajillo-ligero-champinones', 'Pollo al ajillo ligero al vino blanco con champiñones laminados', 'ave_carne_magra', 'lunch', 'otono,invierno,primavera', 370, 39, 10, 16, 25, 'Dorado en cazuela + Reducción', 'assets/img/conejo_pollo_ajillo.jpg', 'https://www.youtube.com/results?search_query=receta+pollo+al+ajillo+casero+saludable+español', 'Sella los dados de pechuga o contramuslo limpio con ajos enteros con piel golpeados y añade champiñones frescos que absorben toda la reducción aromática.', 'Se conserva 3 días en la nevera sin perder jugosidad.', 0),
(23, 'solomillo-pavo-estofado-verduras', 'Solomillo de pavo estofado con zanahoria, puerro y tomillo', 'ave_carne_magra', 'both', 'otono,invierno,primavera', 335, 37, 13, 12, 25, 'Estofado ligero', 'assets/img/guiso_ave.jpg', 'https://www.youtube.com/results?search_query=receta+solomillo+de+pavo+en+salsa+de+verduras', 'Tritura la mitad de las zanahorias y el puerro con el caldo de cocción para lograr una salsa espesa color ámbar de restaurante con menos de 340 kcal.', 'Plato estrella de Batch Cooking: mejora al reposar 24 horas.', 0),
(24, 'pinchos-morunos-pollo-calabacin', 'Pinchos morunos caseros de pollo a la plancha con calabacín', 'ave_carne_magra', 'dinner', 'primavera,verano,otono', 320, 36, 9, 13, 18, 'Plancha / Grill', 'assets/img/aves.jpg', 'https://www.youtube.com/results?search_query=receta+pinchos+morunos+de+pollo+caseros+saludables', 'Prepara el adobo moruno en casa con pimentón dulce, comino, orégano, cúrcuma y ajo; evitas los adobos industriales cargados de dextrosa y grasas ocultas.', 'Deja los dados de pollo marinando en táper desde la víspera.', 0),
(25, 'albondigas-pavo-horno-salsa-espanola', 'Albóndigas de pavo al horno en salsa española de verduras', 'ave_carne_magra', 'lunch', 'otono,invierno,primavera', 385, 36, 22, 15, 30, 'Horneado + Salsa tradicional', 'assets/img/albondigas_salsa.jpg', 'https://www.youtube.com/results?search_query=receta+albondigas+de+pavo+al+horno+en+salsa+española', 'En vez de pasar las albóndigas por harina y freírlas, añade calabacín rallado crudo a la masa de pavo y hornéalas 12 minutos antes de darles un hervor en la salsa.', 'Puedes hornear doble tanda el domingo y congelar la mitad.', 0),
(26, 'conejo-ajillo-cazuela-alcachofas', 'Conejo al ajillo tradicional en cazuela con corazones de alcachofa', 'ave_carne_magra', 'lunch', 'otono,invierno,primavera', 350, 38, 11, 15, 30, 'Cazuela mediterránea', 'assets/img/conejo_pollo_ajillo.jpg', 'https://www.youtube.com/results?search_query=receta+conejo+al+ajillo+con+alcachofas+española', 'La carne de conejo es una de las más magras y ricas en vitamina B12 de la gastronomía española; guisada con alcachofas y romero resulta extraordinariamente ligera.', 'Ideal para dejar hecho el domingo y calentar a fuego suave.', 0),
(27, 'lomo-cerdo-magro-pimientos-piquillo', 'Lomo magro a la plancha con pimientos del piquillo confitados ligeros', 'ave_carne_magra', 'dinner', 'primavera,verano,otono,invierno', 340, 35, 11, 15, 15, 'Plancha vuelta y vuelta', 'assets/img/aves.jpg', 'https://www.youtube.com/results?search_query=receta+lomo+a+la+plancha+con+pimientos+del+piquillo', 'Saltea las tiras de pimiento del piquillo con láminas de ajo a fuego muy suave en su propio jugo; aporta dulzor natural y jugosidad al lomo magro.', 'Los pimientos del piquillo se confitan en 10 minutos el domingo.', 0),
(28, 'pollo-jardinera-guisantes-zanahoria', 'Pollo guisado a la jardinera con guisantes tiernos y zanahoria', 'ave_carne_magra', 'lunch', 'primavera,otono,invierno', 395, 37, 25, 14, 28, 'Guiso casero de toda la vida', 'assets/img/guiso_ave.jpg', 'https://www.youtube.com/results?search_query=receta+pollo+a+la+jardinera+tradicional+español', 'Retira toda la piel del pollo antes de dorarlo; tendrás todo el colágeno y sabor del guiso de las abuelas con menos de la mitad de calorías.', 'Guárdalo con su salsa bien cubierta en táper de cristal.', 0),
(29, 'tiras-pollo-salteadas-pimientos-lechuga', 'Salteado mediterráneo de pollo con pimientos sobre hojas de lechuga', 'ave_carne_magra', 'dinner', 'primavera,verano', 310, 35, 10, 12, 15, 'Salteado rápido', 'assets/img/aves.jpg', 'https://www.youtube.com/results?search_query=receta+salteado+de+pollo+con+pimientos+y+cebolla+saludable', 'Servir las tiras de pollo y pimientos asados sobre hojas crujientes de cogollo de Tudela sustituye las tortitas de harina refinada ahorrando 180 kcal por cena.', 'Aprovecha las tiras de pimiento y cebolla ya cortadas.', 0),
(30, 'pavo-plancha-ensalada-murciana', 'Filetes de pavo a la plancha con ensalada murciana (moje ligero)', 'ave_carne_magra', 'both', 'primavera,verano', 315, 36, 12, 12, 12, 'Plancha + Ensalada fresca', 'assets/img/aves.jpg', 'https://www.youtube.com/results?search_query=receta+moje+murciano+ensalada+española', 'El moje o ensalada murciana con tomate pera, cebolleta tierna y huevo duro es una guarnición hidratante, rica en licopeno y de bajísima densidad calórica.', 'El moje murciano está aún más rico tras reposar 2 horas en frío.', 0),
(31, 'contramuslo-pollo-horno-limon-romero', 'Contramuslo de pollo deshuesado al horno al limón y romero', 'ave_carne_magra', 'lunch', 'primavera,verano,otono,invierno', 380, 36, 18, 16, 25, 'Asado al horno', 'assets/img/conejo_pollo_ajillo.jpg', 'https://www.youtube.com/results?search_query=receta+pollo+al+horno+con+limon+y+romero+española', 'Desengrasa el contramuslo con tijera de cocina antes de hornear con calabacín y patata medida: es mucho más jugoso que la pechuga con apenas 30 kcal de diferencia.', 'Asa el pollo al mismo tiempo que las verduras del Batch Cooking.', 0),

-- 32 a 42: VERDURAS DE LA HUERTA, HUEVOS Y PLATOS DE CUCHARA LIGEROS
(32, 'pisto-manchego-huevo-escalfado', 'Pisto manchego tradicional con huevo campero escalfado', 'verdura_huevo', 'both', 'primavera,verano,otono,invierno', 310, 15, 19, 17, 25, 'Pochado lento + Escalfado', 'assets/img/verduras.jpg', 'https://www.youtube.com/results?search_query=receta+pisto+manchego+casero+con+huevo+española', 'Pocha el calabacín, la berenjena y los pimientos con la sartén tapada a fuego medio-bajo: las hortalizas sueltan su propia agua de vegetación y se cocinan casi sin aceite.', 'El pisto manchego es la base reina del Batch Cooking dominical.', 0),
(33, 'tortilla-calabacin-cebolla-tierna', 'Tortilla jugosa de calabacín y cebolla tierna con mínimo aceite', 'verdura_huevo', 'dinner', 'primavera,verano,otono,invierno', 295, 16, 11, 18, 18, 'Cuajado en sartén antiadherente', 'assets/img/tortilla.jpg', 'https://www.youtube.com/results?search_query=receta+tortilla+de+calabacin+y+cebolla+saludable+española', 'Cocina el calabacín y la cebolla al vapor o microondas en estuche cerrado 5 minutos antes de dorarlos 2 minutos en sartén: consigues máxima jugosidad con solo 1 cucharadita de AOVE.', 'Puedes dejar el relleno de calabacín y cebolla pochado en nevera.', 0),
(34, 'salmorejo-cordobes-ligero-sin-pan', 'Salmorejo cordobés ligero (espesado con calabacín) con huevo y jamón', 'verdura_huevo', 'both', 'primavera,verano', 285, 16, 14, 17, 12, 'Emulsión en frío (Batidora)', 'assets/img/gazpacho_salmorejo.jpg', 'https://www.youtube.com/results?search_query=receta+salmorejo+cordobes+ligero+sin+pan+española', 'Sustituir el pan blanco por dados de calabacín pelado cocido al vapor logra exactamente la misma textura espesa y aterciopelada del salmorejo cordobés restando 220 kcal.', 'Aguanta 4 días en botella de cristal bien fría en la nevera.', 0),
(35, 'gazpacho-andaluz-tradicional-huevo', 'Gazpacho andaluz tradicional sin pan con guarnición y huevo duro', 'verdura_huevo', 'dinner', 'primavera,verano', 260, 13, 15, 15, 12, 'Triturado en frío', 'assets/img/gazpacho_salmorejo.jpg', 'https://www.youtube.com/results?search_query=receta+gazpacho+andaluz+tradicional+sin+pan', 'Tritura los tomates pera muy maduros con pepino, pimiento verde italiano y ajo sin añadir miga de pan; sírvelo en cuenco con dos huevos duros picados para una cena proteica y saciante.', 'Prepáralo el domingo; los sabores se asientan en frío.', 0),
(36, 'menestra-verduras-navarra-huevo-jamon', 'Menestra de verduras a la navarra con huevo poché y jamón magro', 'verdura_huevo', 'both', 'primavera,otono,invierno', 320, 19, 20, 16, 25, 'Vapor + Rehogado ligero', 'assets/img/verduras_rellenas.jpg', 'https://www.youtube.com/results?search_query=receta+menestra+de+verduras+tradicional+española', 'Cuece cada verdura al dente (judía verde, zanahoria, alcachofa y guisantes) y únelas con un refrito ligero de ajo, taquitos de jamón magro y una cucharada de caldo.', 'Deja las verduras hervidas al dente listas en táper.', 0),
(37, 'crema-calabaza-puerro-huevo', 'Crema suave de calabaza asada y puerro con huevo mollet', 'verdura_huevo', 'dinner', 'otono,invierno', 275, 14, 22, 13, 22, 'Cocción y triturado sin nata', 'assets/img/crema_verduras.jpg', 'https://www.youtube.com/results?search_query=receta+crema+de+calabaza+y+puerro+saludable+española', 'En lugar de nata líquida, emulsiona la crema en caliente con una cucharada de requesón o queso fresco 0% batido y corona con un huevo cocido 6 minutos de yema cremosa.', 'La crema se conserva 5 días en tarro hermético.', 0),
(38, 'revuelto-trigueros-ajetes-champinones', 'Revuelto casero de espárragos trigueros, ajetes y champiñones', 'verdura_huevo', 'dinner', 'primavera,otono,invierno', 290, 17, 9, 19, 14, 'Salteado y cuajado suave', 'assets/img/revuelto.jpg', 'https://www.youtube.com/results?search_query=receta+revuelto+de+esparragos+trigueros+y+champiñones', 'Retira la sartén del fuego antes de que el huevo termine de cuajar y remueve enérgicamente: obtendrás un revuelto meloso sin añadir mantequilla.', 'Saltea las verduras previamente y cuaja el huevo al momento.', 0),
(39, 'berenjenas-rellenas-verduras-pavo', 'Berenjenas asadas rellenas de verduras y pavo con requesón', 'verdura_huevo', 'both', 'primavera,verano,otono,invierno', 340, 26, 18, 16, 28, 'Horno / Gratinado sin bechamel', 'assets/img/verduras_rellenas.jpg', 'https://www.youtube.com/results?search_query=receta+berenjenas+rellenas+saludables+sin+bechamel', 'Sustituimos la pesada bechamel de mantequilla y harina por una capa ligera de requesón batido con una pizca de nuez moscada que gratina de maravilla al horno.', 'Puedes dejar las barquitas de berenjena asadas y rellenas el domingo.', 0),
(40, 'tortilla-francesa-hierbas-tomate-alinado', 'Tortilla francesa de finas hierbas con tomate aliñado al orégano', 'verdura_huevo', 'dinner', 'primavera,verano,otono,invierno', 280, 16, 9, 18, 10, 'Plancha rápida (5 min)', 'assets/img/tortilla.jpg', 'https://www.youtube.com/results?search_query=receta+tortilla+francesa+jugosa+con+tomate+aliñado', 'Bate los huevos con una cucharada sopera de agua fría y perejil fresco picado: el vapor de agua hace que la tortilla suba esponjosa sin requerir más aceite.', 'Cena salvavidas lista en 5 minutos exactos.', 0),
(41, 'crema-calabacin-ligera-tiras-pavo', 'Crema de calabacín y puerro sin nata con tiras de pavo tostadas', 'verdura_huevo', 'dinner', 'primavera,verano,otono,invierno', 285, 21, 15, 14, 20, 'Cocción suave y batido', 'assets/img/crema_verduras.jpg', 'https://www.youtube.com/results?search_query=receta+crema+de+calabacin+saludable+sin+nata+española', 'Pela parcialmente el calabacín (en franjas tipo cebra) para mantener la fibra de la piel y conseguir un color verde pistacho luminoso y apetecible.', 'Prepara 1 litro de crema el domingo para 2 cenas de la semana.', 0),
(42, 'judias-verdes-patata-refrito-pimenton', 'Judías verdes planas al vapor con patata y refrito de ajo y pimentón', 'verdura_huevo', 'dinner', 'primavera,otono,invierno', 295, 14, 28, 13, 20, 'Vapor + Refrito tradicional medido', 'assets/img/verduras_rellenas.jpg', 'https://www.youtube.com/results?search_query=receta+judias+verdes+con+patatas+y+ajo+pimenton+española', 'Acompaña las judías verdes y la patata cocida al vapor con un huevo duro picado y el clásico refrito español de ajo dorado y pimentón de la Vera retirado del fuego.', 'Las judías y patatas pueden cocerse al vapor en el Batch Cooking.', 0);

