INSERT INTO `recipes` (`id`, `slug`, `name`, `category`, `meal_slot`, `seasons`, `kcal`, `protein_g`, `carbs_g`, `fat_g`, `prep_minutes`, `cooking_method`, `is_friday_fixed`, `image_url`, `youtube_url`, `chef_tip`, `batch_prep_tip`) VALUES
(43, 'lentejas-castellanas-ligeras-laurel', 'Lentejas castellanas estofadas al laurel y pimentón sin grasa', 'legumbre', 'lunch', 'otono,invierno,primavera', 395, 22, 53, 8, 25, 'Guiso tradicional', 0, 'assets/img/legumbres.jpg', 'https://www.youtube.com/results?search_query=receta%20casera%20Lentejas%20castellanas%20estofadas%20al%20laurel%20y%20piment%C3%B3n%20sin%20grasa%20espa%C3%B1ola%20saludable', 'Emulsiona el caldo triturando una zanahoria cocida con una cucharadita de AOVE en crudo.', 'Conserva hasta 4 días en frigorífico.'),
(44, 'garbanzos-pedrosillanos-calabaza-romero', 'Garbanzos pedrosillanos guisados con calabaza y romero fresco', 'legumbre', 'lunch', 'otono,invierno', 390, 20, 50, 9, 22, 'Estofado suave', 0, 'assets/img/garbanzos.jpg', 'https://www.youtube.com/results?search_query=receta%20casera%20Garbanzos%20pedrosillanos%20guisados%20con%20calabaza%20y%20romero%20fresco%20espa%C3%B1ola%20saludable', 'La calabaza aporta dulzor y espesa el caldo sin necesidad de harinas refinadas.', 'Ideal para preparar el domingo.'),
(45, 'alubias-blancas-marinera-huerta-setas', 'Alubias blancas a la marinera de huerta (con setas y ajo perejil)', 'legumbre', 'lunch', 'otono,invierno,primavera', 380, 21, 49, 9, 20, 'Cazuela ligada', 0, 'assets/img/alubias_ensalada.jpg', 'https://www.youtube.com/results?search_query=receta%20casera%20Alubias%20blancas%20a%20la%20marinera%20de%20huerta%20(con%20setas%20y%20ajo%20perejil)%20espa%C3%B1ola%20saludable', 'Sustituimos cualquier molusco por setas laminadas con picada de ajo, perejil y limón.', 'Guarda en táper de cristal.'),
(46, 'potaje-vigilia-espinacas-huevo-sin-pescado', 'Potaje tradicional de garbanzos, espinacas y huevo duro', 'legumbre', 'lunch', 'invierno,primavera', 415, 24, 48, 12, 22, 'Cuchara tradicional', 0, 'assets/img/garbanzos.jpg', 'https://www.youtube.com/results?search_query=receta%20casera%20Potaje%20tradicional%20de%20garbanzos%2C%20espinacas%20y%20huevo%20duro%20espa%C3%B1ola%20saludable', 'Versión 100% libre de bacalao: el huevo duro campero aporta proteína de alto valor biológico.', 'Añade la espinaca al final.'),
(47, 'ensalada-garbanzos-mediterranea-pepino', 'Ensalada fresca de garbanzos con pepino, tomate pera y orégano', 'legumbre', 'lunch', 'primavera,verano', 365, 18, 46, 10, 10, 'Ensalada fresca', 0, 'assets/img/alubias_ensalada.jpg', 'https://www.youtube.com/results?search_query=receta%20casera%20Ensalada%20fresca%20de%20garbanzos%20con%20pepino%2C%20tomate%20pera%20y%20or%C3%A9gano%20espa%C3%B1ola%20saludable', 'Aliña con zumo de limón fresco y orégano para potenciar el sabor con mínimo aceite.', 'Lista en 10 minutos sin encender el fuego.'),
(48, 'lentejas-estofadas-puerro-champinones', 'Lentejas pardinas estofadas con puerro tierno y champiñones', 'legumbre', 'lunch', 'otono,invierno,primavera', 390, 23, 51, 8, 24, 'Estofado en olla', 0, 'assets/img/legumbres.jpg', 'https://www.youtube.com/results?search_query=receta%20casera%20Lentejas%20pardinas%20estofadas%20con%20puerro%20tierno%20y%20champi%C3%B1ones%20espa%C3%B1ola%20saludable', 'El umami natural del champiñón enriquece el caldo de las lentejas sin carnes grasas.', 'Congela o refrigera perfectamente.'),
(49, 'alubias-blancas-vinagreta-pimientos', 'Alubias blancas en vinagreta templada de pimientos y cebolleta', 'legumbre', 'lunch', 'primavera,verano', 370, 19, 47, 10, 12, 'Ensalada templada', 0, 'assets/img/alubias_ensalada.jpg', 'https://www.youtube.com/results?search_query=receta%20casera%20Alubias%20blancas%20en%20vinagreta%20templada%20de%20pimientos%20y%20cebolleta%20espa%C3%B1ola%20saludable', 'Pica los pimientos muy menudos para que cada cucharada tenga textura crujiente.', 'Mejora tras 2 horas en la nevera.'),
(50, 'garbanzos-rehogados-acelgas-ajo-asado', 'Garbanzos rehogados con acelgas frescas y crema de ajo asado', 'legumbre', 'lunch', 'otono,invierno,primavera', 385, 20, 48, 10, 18, 'Rehogado en sartén', 0, 'assets/img/garbanzos.jpg', 'https://www.youtube.com/results?search_query=receta%20casera%20Garbanzos%20rehogados%20con%20acelgas%20frescas%20y%20crema%20de%20ajo%20asado%20espa%C3%B1ola%20saludable', 'El ajo asado envuelto en papel de horno da cremosidad sin aportar calorías extra.', 'Usa acelga fresca lavada.'),
(51, 'lentejas-verdes-calabaza-espinacas', 'Lentejas guisadas con dados de calabaza y hojas de espinaca', 'legumbre', 'lunch', 'otono,invierno', 395, 22, 52, 9, 25, 'Guiso suave', 0, 'assets/img/garbanzos.jpg', 'https://www.youtube.com/results?search_query=receta%20casera%20Lentejas%20guisadas%20con%20dados%20de%20calabaza%20y%20hojas%20de%20espinaca%20espa%C3%B1ola%20saludable', 'Incorpora las espinacas con el fuego ya apagado para que se cocinen con el calor residual.', 'Rico en hierro y betacarotenos.'),
(52, 'garbanzos-con-pisto-manchego', 'Garbanzos dorados con pisto manchego tradicional', 'legumbre', 'lunch', 'primavera,verano,otono,invierno', 405, 19, 50, 11, 16, 'Salteado con fondo', 0, 'assets/img/garbanzos.jpg', 'https://www.youtube.com/results?search_query=receta%20casera%20Garbanzos%20dorados%20con%20pisto%20manchego%20tradicional%20espa%C3%B1ola%20saludable', 'Aprovecha el pisto casero del domingo para tener un plato de legumbres gourmet en 8 minutos.', 'Combina fibra soluble e insoluble.'),
(53, 'pochas-navarras-ligeras-verduras', 'Pochas a la navarra ligeras con verduras de temporada', 'legumbre', 'lunch', 'verano,otono', 390, 21, 50, 9, 25, 'Cuchara suave', 0, 'assets/img/alubias_ensalada.jpg', 'https://www.youtube.com/results?search_query=receta%20casera%20Pochas%20a%20la%20navarra%20ligeras%20con%20verduras%20de%20temporada%20espa%C3%B1ola%20saludable', 'Mueve la cazuela en vaivén sin meter cuchara para que las alubias no se rompan y traben solas.', 'Plato emblemático de la huerta navarra.'),
(54, 'ensalada-lentejas-atun-fresco-tomate', 'Ensalada mediterránea de lentejas con tomate rosa y atún a la plancha', 'legumbre', 'lunch', 'primavera,verano', 415, 30, 45, 11, 15, 'Fresco + Plancha', 0, 'assets/img/alubias_ensalada.jpg', 'https://www.youtube.com/results?search_query=receta%20casera%20Ensalada%20mediterr%C3%A1nea%20de%20lentejas%20con%20tomate%20rosa%20y%20at%C3%BAn%20a%20la%20plancha%20espa%C3%B1ola%20saludable', 'Marca el atún fresco en dados con hierbas provenzales justo antes de emplatar.', 'Altísimo poder saciante.'),
(55, 'garbanzos-alcachofas-limon-tomillo', 'Guiso mediterráneo de garbanzos con alcachofas al limón y tomillo', 'legumbre', 'lunch', 'invierno,primavera', 395, 20, 49, 10, 24, 'Guiso aromático', 0, 'assets/img/garbanzos.jpg', 'https://www.youtube.com/results?search_query=receta%20casera%20Guiso%20mediterr%C3%A1neo%20de%20garbanzos%20con%20alcachofas%20al%20lim%C3%B3n%20y%20tomillo%20espa%C3%B1ola%20saludable', 'Un toque de ralladura de limón al final levanta el sabor de las alcachofas sin añadir sal.', 'Excelente depurativo hepático.'),
(56, 'alubias-blancas-esparragos-trigueros-ajetes', 'Alubias blancas salteadas con espárragos trigueros y ajetes', 'legumbre', 'lunch', 'primavera,verano', 385, 20, 47, 10, 15, 'Salteado rápido', 0, 'assets/img/alubias_ensalada.jpg', 'https://www.youtube.com/results?search_query=receta%20casera%20Alubias%20blancas%20salteadas%20con%20esp%C3%A1rragos%20trigueros%20y%20ajetes%20espa%C3%B1ola%20saludable', 'Deja los trigueros crujientes para favorecer la masticación y la señal de saciedad.', 'Se prepara en una sola sartén.'),
(57, 'crema-lentejas-zanahoria-huevo-picado', 'Crema suave de lentejas y zanahoria con huevo duro picado', 'legumbre', 'lunch', 'otono,invierno', 400, 24, 50, 10, 25, 'Cocción y batido', 0, 'assets/img/legumbres.jpg', 'https://www.youtube.com/results?search_query=receta%20casera%20Crema%20suave%20de%20lentejas%20y%20zanahoria%20con%20huevo%20duro%20picado%20espa%C3%B1ola%20saludable', 'Triturar las lentejas con zanahoria y puerro evita gases y facilita las digestiones lentas.', 'Guarda en tarros individuales.'),
(58, 'hummus-cuchara-templado-verduras-asadas', 'Cazuela templada de garbanzos con berenjena y pimiento asado', 'legumbre', 'lunch', 'primavera,verano,otono', 395, 19, 49, 11, 18, 'Horno / Cazuela', 0, 'assets/img/alubias_ensalada.jpg', 'https://www.youtube.com/results?search_query=receta%20casera%20Cazuela%20templada%20de%20garbanzos%20con%20berenjena%20y%20pimiento%20asado%20espa%C3%B1ola%20saludable', 'Mezcla los garbanzos calientes con las tiras de escalivada y pimentón dulce.', 'Aprovecha el horneado dominical.'),
(59, 'lentejas-judias-verdes-patata-nueva', 'Lentejas estofadas con judías verdes planas y patata nueva medida', 'legumbre', 'lunch', 'primavera,otono,invierno', 410, 21, 55, 8, 26, 'Olla tradicional', 0, 'assets/img/legumbres.jpg', 'https://www.youtube.com/results?search_query=receta%20casera%20Lentejas%20estofadas%20con%20jud%C3%ADas%20verdes%20planas%20y%20patata%20nueva%20medida%20espa%C3%B1ola%20saludable', 'Chasca la patata haciéndola crujir para que suelte su fécula de forma controlada.', 'Clásico de las casas españolas.'),
(60, 'alubias-blancas-piquillos-pavo-magro', 'Alubias blancas guisadas con tiras de pimiento del piquillo y pavo', 'legumbre', 'lunch', 'otono,invierno,primavera', 415, 29, 47, 10, 20, 'Guiso ligero', 0, 'assets/img/alubias_ensalada.jpg', 'https://www.youtube.com/results?search_query=receta%20casera%20Alubias%20blancas%20guisadas%20con%20tiras%20de%20pimiento%20del%20piquillo%20y%20pavo%20espa%C3%B1ola%20saludable', 'Los dados de pechuga de pavo sustituyen al embutido reduciendo un 70% la grasa saturada.', 'Muy rico en proteína magra.'),
(61, 'garbanzos-salteados-espinacas-huevo-escalfado', 'Garbanzos salteados con espinacas tiernas y huevo escalfado', 'legumbre', 'lunch', 'primavera,otono,invierno', 420, 25, 46, 13, 16, 'Sartén + Escalfado', 0, 'assets/img/garbanzos.jpg', 'https://www.youtube.com/results?search_query=receta%20casera%20Garbanzos%20salteados%20con%20espinacas%20tiernas%20y%20huevo%20escalfado%20espa%C3%B1ola%20saludable', 'La yema líquida del huevo escalfado actúa como salsa sedosa sobre los garbanzos.', 'Cena o comida única completísima.'),
(62, 'ensalada-campera-lentejas-pimiento-huevo', 'Ensalada campera de lentejas con tomate, pimiento verde y huevo', 'legumbre', 'lunch', 'primavera,verano', 385, 23, 47, 11, 14, 'Ensalada fría', 0, 'assets/img/alubias_ensalada.jpg', 'https://www.youtube.com/results?search_query=receta%20casera%20Ensalada%20campera%20de%20lentejas%20con%20tomate%2C%20pimiento%20verde%20y%20huevo%20espa%C3%B1ola%20saludable', 'Enjuaga bien la lenteja cocida hasta que deje de hacer espuma antes de aliñar.', 'Perfecta para llevar en táper al trabajo.'),
(63, 'potaje-garbanzos-calabacin-puerro-azafran', 'Potaje suave de garbanzos con calabacín, puerro y hebras de azafrán', 'legumbre', 'lunch', 'otono,invierno,primavera', 385, 19, 49, 10, 22, 'Cuchara aromática', 0, 'assets/img/garbanzos.jpg', 'https://www.youtube.com/results?search_query=receta%20casera%20Potaje%20suave%20de%20garbanzos%20con%20calabac%C3%ADn%2C%20puerro%20y%20hebras%20de%20azafr%C3%A1n%20espa%C3%B1ola%20saludable', 'Tuesta ligeramente las hebras de azafrán para perfumar todo el guiso sin calorías.', 'Reconfortante y muy digestivo.'),
(64, 'alubias-blancas-tomate-natural-albahaca', 'Alubias blancas estofadas en salsa de tomate casero y orégano', 'legumbre', 'lunch', 'primavera,verano,otono,invierno', 380, 19, 50, 9, 18, 'Cazuela suave', 0, 'assets/img/alubias_ensalada.jpg', 'https://www.youtube.com/results?search_query=receta%20casera%20Alubias%20blancas%20estofadas%20en%20salsa%20de%20tomate%20casero%20y%20or%C3%A9gano%20espa%C3%B1ola%20saludable', 'Usa el tomate natural reducido del Batch Cooking para tener el plato listo en 10 minutos.', 'Sabor mediterráneo puro.'),
(65, 'lentejas-piquillos-zanahoria-comino', 'Lentejas pardinas con pimientos del piquillo y toque de comino', 'legumbre', 'lunch', 'otono,invierno,primavera', 390, 21, 52, 8, 24, 'Guiso tradicional', 0, 'assets/img/legumbres.jpg', 'https://www.youtube.com/results?search_query=receta%20casera%20Lentejas%20pardinas%20con%20pimientos%20del%20piquillo%20y%20toque%20de%20comino%20espa%C3%B1ola%20saludable', 'El comino molido evita la flatulencia propia de las legumbres y realza su sabor.', 'Tritura dos piquillos en el caldo.'),
(66, 'garbanzos-champinones-ajillo-perejil', 'Garbanzos al ajillo ligero con champiñones y perejil fresco', 'legumbre', 'lunch', 'primavera,verano,otono,invierno', 385, 20, 47, 11, 15, 'Salteado rápido', 0, 'assets/img/garbanzos.jpg', 'https://www.youtube.com/results?search_query=receta%20casera%20Garbanzos%20al%20ajillo%20ligero%20con%20champi%C3%B1ones%20y%20perejil%20fresco%20espa%C3%B1ola%20saludable', 'Desglasa la sartén con un chorrito de limón y caldo de verduras para no usar más aceite.', 'Listo en un cuarto de hora.'),
(67, 'ensalada-alubias-murciana-tomate-huevo', 'Moje murciano de alubias blancas con tomate pera y huevo duro', 'legumbre', 'lunch', 'primavera,verano', 375, 22, 45, 10, 12, 'Fresco sin fuego', 0, 'assets/img/alubias_ensalada.jpg', 'https://www.youtube.com/results?search_query=receta%20casera%20Moje%20murciano%20de%20alubias%20blancas%20con%20tomate%20pera%20y%20huevo%20duro%20espa%C3%B1ola%20saludable', 'Aprovecha el jugo natural del tomate maduro para hidratar las alubias.', 'Ideal para días calurosos.'),
(68, 'lentejas-calabacin-berenjena-huerta', 'Lentejas de la huerta con dados de berenjena y calabacín', 'legumbre', 'lunch', 'primavera,verano,otono', 390, 21, 51, 9, 25, 'Guiso de huerta', 0, 'assets/img/legumbres.jpg', 'https://www.youtube.com/results?search_query=receta%20casera%20Lentejas%20de%20la%20huerta%20con%20dados%20de%20berenjena%20y%20calabac%C3%ADn%20espa%C3%B1ola%20saludable', 'Corta las hortalizas en cubos pequeños para que se integren con la lenteja pardina.', 'Alto contenido en fibra saciante.'),
(69, 'garbanzos-judias-verdes-tomate-concasse', 'Garbanzos templados con judías verdes al vapor y tomate concassé', 'legumbre', 'lunch', 'primavera,verano,otono', 380, 19, 48, 10, 18, 'Vapor + Rehogado', 0, 'assets/img/alubias_ensalada.jpg', 'https://www.youtube.com/results?search_query=receta%20casera%20Garbanzos%20templados%20con%20jud%C3%ADas%20verdes%20al%20vapor%20y%20tomate%20concass%C3%A9%20espa%C3%B1ola%20saludable', 'Las judías verdes al dente obligan a masticar despacio aumentando la saciedad.', 'Muy bajo índice glucémico.'),
